def valid(number):
    """Return True if the card number is valid per the Luhn algorithm.

    The input must be a string. Single spaces between digits are allowed
    and ignored. Returns False if, after removing spaces, there are fewer
    than two characters or any character is not a digit 0-9.
    """
    if not isinstance(number, str):
        return False

    digits = number.replace(" ", "")
    if len(digits) < 2:
        return False
    if not all("0" <= ch <= "9" for ch in digits):
        return False

    total = 0
    for index, ch in enumerate(reversed(digits)):
        digit = ord(ch) - ord("0")
        if index % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit

    return total % 10 == 0
